@pytest.mark.parametrize('camera',['1280','640']) @pytest.mark.parametrize('name,height,distance,azimuth,roll,shift,occlusion',WORKCELL_CASES) def test_closed_loop(camera,name,height,distance,azimuth,roll,shift,occlusion): K,D,info=intrinsics(f'examples/camera_{camera}.json');wh=[info['width'],info['height']] T,geometry=workcell_pose(SPEC,height,distance,azimuth,roll,shift) assert .65-1e-9 <= geometry['height_m'] <= .8+1e-9 assert .8-1e-9 <= geometry['distance_m'] <= 1.+1e-9 assert 30 <= geometry['normal_angle_deg'] <= 60 assert 30 <= geometry['plane_view_angle_deg'] <= 60 name=f'{camera}_{name}';directory=Path('out/review4_single');directory.mkdir(exist_ok=True) base=directory/name image=render(SPEC,T,K,wh,occlude=occlusion,noise_seed=17) cv2.imwrite(str(base)+'.png',image) metrics={'camera':camera,'case':name,'geometry':geometry,'occlusion':occlusion, 'min_cell_px':minimum_cell_px(SPEC,T,K),'detected':False,'meets_pose_gate':False} try: detection,overlay=detect(image,SPEC,K,D) except ValueError as exc: metrics['error']=str(exc);save_json(str(base)+'_metrics.json',metrics) if camera=='1280':raise return save_json(str(base)+'_detection.json',detection) cv2.imwrite(str(base)+'_overlay.png',overlay) recovered=np.array(detection['T_camera_optical_board']) wb=tabletop_board(SPEC) wb[:3,3]+=wb[:3,:3]@np.r_[shift,0.] ext=extrinsics([detection],{'T_world_board':wb.tolist()},SPEC) truth=wb@np.linalg.inv(T);estimate=np.array(ext['T_world_camera_optical']) dt=float(np.linalg.norm(estimate[:3,3]-truth[:3,3])*1000);dr=rotation_error(estimate[:3,:3],truth[:3,:3]) dbt=float(np.linalg.norm(recovered[:3,3]-T[:3,3])*1000);dbr=rotation_error(recovered[:3,:3],T[:3,:3]) gray=analyze(image,detection,SPEC) metrics.update(detected=True,corners=len(detection['corner_ids']),board_translation_error_mm=dbt, board_rotation_error_deg=dbr,camera_translation_error_mm=dt,camera_rotation_error_deg=dr, reprojection_median_px=detection['reprojection_median_px'],reprojection_p95_px=detection['reprojection_p95_px'], gray_monotonic=gray['monotonic_increasing'],gray_visible=sum(p['valid'] for p in gray['patches'])) metrics['meets_pose_gate']=bool(dbt<=2 and dt<=2 and dbr<=.2 and dr<=.2 and detection['reprojection_median_px']<=.5) metrics['workspace_projection']=projection_metrics(truth,estimate,K,D,*wh) save_json(str(base)+'_metrics.json',metrics);save_json(str(base)+'_gray.json',gray) if camera=='1280': assert gray['monotonic_increasing'] assert metrics['workspace_projection']['max_px']<=1.0 > assert metrics['workspace_projection']['mean_px']<=.5 E assert 0.6282244469695193 <= 0.5
